from __future__ import annotations

import json
import subprocess
from pathlib import Path

from .scanners import CheckResult


def _gh_json(args: list[str], cwd: Path) -> object | None:
    try:
        p = subprocess.run(
            ["gh", *args],
            cwd=str(cwd),
            capture_output=True,
            text=True,
            check=False,
            timeout=60,
        )
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return None
    if p.returncode != 0:
        return None
    try:
        return json.loads(p.stdout)
    except json.JSONDecodeError:
        return None


def open_gap_issues(repo: Path, results: list[CheckResult]) -> list[str]:
    """Create or update issues for failing non-waived scanners. Returns messages."""
    messages: list[str] = []
    # Ensure labels
    subprocess.run(
        [
            "gh",
            "label",
            "create",
            "house-scan-gap",
            "--color",
            "B60205",
            "--description",
            "House scanner compliance gap",
        ],
        cwd=str(repo),
        capture_output=True,
        check=False,
    )
    subprocess.run(
        [
            "gh",
            "label",
            "create",
            "security-tooling",
            "--color",
            "0E8A16",
            "--description",
            "Security tooling",
        ],
        cwd=str(repo),
        capture_output=True,
        check=False,
    )

    existing = _gh_json(
        [
            "issue",
            "list",
            "--label",
            "house-scan-gap",
            "--state",
            "open",
            "--json",
            "number,body,title",
            "--limit",
            "50",
        ],
        repo,
    )
    if not isinstance(existing, list):
        messages.append("WARN: gh not available or not authenticated; skip --open-issues")
        return messages

    for r in results:
        if r.status not in ("fail", "error"):
            continue
        marker = f"scanner_id:{r.scanner_id}"
        body = (
            f"## House scan gap\n\n"
            f"`{marker}`\n\n"
            f"| Field | Value |\n|-------|-------|\n"
            f"| Scanner | {r.name} (`{r.scanner_id}`) |\n"
            f"| Status | `{r.status}` |\n"
            f"| Raw compliance % | {r.compliance_pct}% |\n"
            f"| Message | {r.message} |\n"
            f"| Waiver path | `{r.waiver_path or 'security/waivers/' + r.scanner_id + '.yaml'}` |\n\n"
            f"**Action:** fix findings **or** complete a **per-scanner** waiver at "
            f"`security/waivers/{r.scanner_id}.yaml` (reason ≥20, owner, ticket, expires_on).\n\n"
            f"_Generated by house_scan. Do not put secrets in this issue._\n"
        )
        title = f"[house-scan] Gap: {r.scanner_id} ({r.compliance_pct}%)"
        found_num = None
        for issue in existing:
            if not isinstance(issue, dict):
                continue
            if marker in (issue.get("body") or ""):
                found_num = issue.get("number")
                break
        if found_num:
            subprocess.run(
                ["gh", "issue", "comment", str(found_num), "--body", body],
                cwd=str(repo),
                capture_output=True,
                check=False,
            )
            messages.append(f"Updated issue #{found_num} for {r.scanner_id}")
        else:
            p = subprocess.run(
                [
                    "gh",
                    "issue",
                    "create",
                    "--title",
                    title,
                    "--body",
                    body,
                    "--label",
                    "house-scan-gap",
                    "--label",
                    "security-tooling",
                ],
                cwd=str(repo),
                capture_output=True,
                text=True,
                check=False,
            )
            if p.returncode == 0:
                messages.append(f"Opened {p.stdout.strip()} for {r.scanner_id}")
            else:
                messages.append(f"WARN: failed to open issue for {r.scanner_id}: {p.stderr}")
    return messages
